INSERT INTO `rainlab_blog_posts` VALUES (1,NULL,'First blog post','first-blog-post','The first ever blog post is here. It might be a good idea to update this post with some more relevant content.','This is your first ever **blog post**! It might be a good idea to update this post with some more relevant content.\r\n\r\nYou can edit this content by selecting **Blog** from the administration back-end menu.\r\n\r\n*Enjoy the good times!*','<p>This is your first ever <strong>blog post</strong>! It might be a good idea to update this post with some more relevant content.</p>\n<p>You can edit this content by selecting <strong>Blog</strong> from the administration back-end menu.</p>\n<p><em>Enjoy the good times!</em></p>','2019-02-10 20:24:07',1,'2019-02-10 20:24:07','2020-07-23 16:01:15',NULL),(2,1,'User Types  - View and create system users','user-types','Permision: Admin only, Who can access the website and what are the functions','View and create system users - Administrators Only\r\n* Tab : Users\r\n* Link: http://bt-industrial.co.za/backend/rainlab/user/users\r\n\r\nFunction:\r\n* Create New User\r\n* Activate and Deactivate user\r\n* Assign user to user groups/type\r\n* Impersonate user – Ability to log in to portal as user\r\n\r\n\r\n**Sales**\r\n - Has Create, View and Edit permissions on Quoting and Invoicing functions\r\n - Can request permission for a discount from Executive User\r\n - Can request production run once quote and invoice have been accepted\r\n\r\n\r\n**Production Manager**\r\n - Role to come\r\n \r\n\r\n**Finance Manager**\r\n - Role to come\r\n \r\n\r\n**Executive User**\r\n - Role to come\r\n \r\n\r\n**Stock Room Clerk**\r\n - Role to come\r\n\r\n \r\n\r\n![](http://bailaerp.bt-industrial.co.za/storage/app/media/Screenshot_2019-03-30%20Manage%20Users%20OctoberCMS.png)','<p>View and create system users - Administrators Only</p>\n<ul>\n<li>Tab : Users</li>\n<li>Link: <a href=\"http://bt-industrial.co.za/backend/rainlab/user/users\">http://bt-industrial.co.za/backend/rainlab/user/users</a></li>\n</ul>\n<p>Function:</p>\n<ul>\n<li>Create New User</li>\n<li>Activate and Deactivate user</li>\n<li>Assign user to user groups/type</li>\n<li>Impersonate user – Ability to log in to portal as user</li>\n</ul>\n<p><strong>Sales</strong></p>\n<ul>\n<li>Has Create, View and Edit permissions on Quoting and Invoicing functions</li>\n<li>Can request permission for a discount from Executive User</li>\n<li>Can request production run once quote and invoice have been accepted</li>\n</ul>\n<p><strong>Production Manager</strong></p>\n<ul>\n<li>Role to come</li>\n</ul>\n<p><strong>Finance Manager</strong></p>\n<ul>\n<li>Role to come</li>\n</ul>\n<p><strong>Executive User</strong></p>\n<ul>\n<li>Role to come</li>\n</ul>\n<p><strong>Stock Room Clerk</strong></p>\n<ul>\n<li>Role to come</li>\n</ul>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/media/Screenshot_2019-03-30%20Manage%20Users%20OctoberCMS.png\" alt=\"\" /></p>','2019-03-01 10:35:21',1,'2019-03-28 10:33:17','2021-08-30 07:03:42',NULL),(5,1,'How To Access The Portal - Backend','how-access-portal-backend','Permision: Admin only','**Back end user – Administrator**\r\n* Use the link: http://bt-industrial.co.za/backend\r\n* Only Administrators\r\n* This system was developed in OCTOBER CMS (https://octobercms.com/)\r\n\r\n \r\n![](/storage/app/media/Screenshot_2019-03-30%20Administration%20Area.png)','<p><strong>Back end user – Administrator</strong></p>\n<ul>\n<li>Use the link: <a href=\"http://bt-industrial.co.za/backend\">http://bt-industrial.co.za/backend</a></li>\n<li>Only Administrators</li>\n<li>This system was developed in OCTOBER CMS (<a href=\"https://octobercms.com/\">https://octobercms.com/</a>)</li>\n</ul>\n<p><img src=\"/storage/app/media/Screenshot_2019-03-30%20Administration%20Area.png\" alt=\"\" /></p>','2019-03-06 13:41:46',1,'2019-03-30 13:40:44','2021-08-30 07:05:42',NULL),(6,1,'How To Access The Portal - Front end user','how-access-portal-front-end-user','Accessing portal','**Front end user – Day to day user**\r\n* Link: http://bt-industrial.co.za\r\n* You need user credentials to have access to the system. Contact system administrator for user access\r\n\r\n\r\n\r\n![](/storage/app/media/Screenshot_2019-03-30%20Screenshot.png)','<p><strong>Front end user – Day to day user</strong></p>\n<ul>\n<li>Link: <a href=\"http://bt-industrial.co.za\">http://bt-industrial.co.za</a></li>\n<li>You need user credentials to have access to the system. Contact system administrator for user access</li>\n</ul>\n<p><img src=\"/storage/app/media/Screenshot_2019-03-30%20Screenshot.png\" alt=\"\" /></p>','2019-03-06 02:00:00',1,'2019-03-30 13:44:12','2021-08-30 06:49:05',NULL),(7,1,'View and create user groups/type','view-and-create-user-groupstype','Permission: Admin only','Administrators Only\r\n* Tab: Users > User Groups\r\n* Link: http://bt-industrial.co.za/backend/rainlab/user/usergroups\r\n\r\nFunctions\r\n* View User Groups\r\n* Create new user groups\r\n\r\n\r\n![](/storage/app/media/Screenshot_2019-03-30%20Manage%20Groups%20OctoberCMS.png)','<p>Administrators Only</p>\n<ul>\n<li>Tab: Users &gt; User Groups</li>\n<li>Link: <a href=\"http://bt-industrial.co.za/backend/rainlab/user/usergroups\">http://bt-industrial.co.za/backend/rainlab/user/usergroups</a></li>\n</ul>\n<p>Functions</p>\n<ul>\n<li>View User Groups</li>\n<li>Create new user groups</li>\n</ul>\n<p><img src=\"/storage/app/media/Screenshot_2019-03-30%20Manage%20Groups%20OctoberCMS.png\" alt=\"\" /></p>','2019-03-06 02:00:00',1,'2019-03-30 13:56:07','2021-08-30 07:04:27',NULL),(8,1,'How to create Data Pack','how-create-data-pack','','Steps:\r\n1. Login To the ERP\'s Backend\r\n2. Go To the QC Tab (in there, you will see Data Pack)\r\n3. Go into Data Pack, New Datapack\r\n4. Fill in the fields. The most important ones are the quote and the item from that quote.','<p>Steps:</p>\n<ol>\n<li>Login To the ERP\'s Backend</li>\n<li>Go To the QC Tab (in there, you will see Data Pack)</li>\n<li>Go into Data Pack, New Datapack</li>\n<li>Fill in the fields. The most important ones are the quote and the item from that quote.</li>\n</ol>','2020-03-17 13:48:51',1,'2020-03-17 13:48:31','2021-08-30 07:10:12',NULL),(9,1,'How to Export and Import Clients','how-export-import','How to export and import clients to the erp','**NOTE**: You need access to the ERP backend to access clients.\r\n\r\nClients tab is fount under **Sales** Tab.\r\n\r\nThere are there are 2 buttons to export and import.\r\n\r\n\r\n![import-export-clients-btns.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/5d4/cd0/5ef5d4cd00696158843737.jpg)\r\n\r\n**Export**: \r\n\r\n* It will export **mimimum** clients details. This function is design mailnly for Finance to update \"Limit\"\r\n\r\n**Import**:\r\n\r\n* This function is design mailnly for Finance to update \"Limit\"\r\n* You can only import what has been exported\r\n* Records are linked by ID, meaning you can not import to create new client. use new client button to create.\r\n\r\n**How to Import**\r\n1. Export CSV from ERP\r\n2. Make your edits on that particular CSV.\r\n3. Go to import function and upload the the new updated CSV\r\n4. Link up the  coloums by clicking the button \"Auto Match Columns\" \r\n5. Optional: you can choose to ignore other fields by **Draging and Droping them from Right to Left**\r\n6. Finish off by clicking \"Import Client\"\r\n\r\nThings to look out for is the date formats:\r\n2020/01/09 to \'2020-01-09\r\n\r\n\r\n\r\n![import1.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/5d8/892/5ef5d88927c74446817612.jpg)','<p><strong>NOTE</strong>: You need access to the ERP backend to access clients.</p>\n<p>Clients tab is fount under <strong>Sales</strong> Tab.</p>\n<p>There are there are 2 buttons to export and import.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/5d4/cd0/5ef5d4cd00696158843737.jpg\" alt=\"import-export-clients-btns.JPG\" /></p>\n<p><strong>Export</strong>: </p>\n<ul>\n<li>It will export <strong>mimimum</strong> clients details. This function is design mailnly for Finance to update &quot;Limit&quot;</li>\n</ul>\n<p><strong>Import</strong>:</p>\n<ul>\n<li>This function is design mailnly for Finance to update &quot;Limit&quot;</li>\n<li>You can only import what has been exported</li>\n<li>Records are linked by ID, meaning you can not import to create new client. use new client button to create.</li>\n</ul>\n<p><strong>How to Import</strong></p>\n<ol>\n<li>Export CSV from ERP</li>\n<li>Make your edits on that particular CSV.</li>\n<li>Go to import function and upload the the new updated CSV</li>\n<li>Link up the  coloums by clicking the button &quot;Auto Match Columns&quot; </li>\n<li>Optional: you can choose to ignore other fields by <strong>Draging and Droping them from Right to Left</strong></li>\n<li>Finish off by clicking &quot;Import Client&quot;</li>\n</ol>\n<p>Things to look out for is the date formats:\n2020/01/09 to \'2020-01-09</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/5d8/892/5ef5d88927c74446817612.jpg\" alt=\"import1.JPG\" /></p>','2020-06-26 12:28:07',1,'2020-06-26 12:27:51','2021-08-30 07:17:24',NULL),(10,1,'Sending quote in to Production','sending-quote-production','How to send quote to production','A quote can be sent into production from the Front End.\r\n\r\nNew: Only quotes that belong to Client can be sent to production. \r\n\r\nHow:\r\n- Set up new Client if it does not exist \r\n- Go to the back end to find the Quote\r\n- **Link the Client to the Quote** (You will not be able to send to production if you skip this step)\r\n- Then go back to the frond end and you will be able to send to production\r\n- If account has been blocked you will not be able to send to production\r\n\r\n<p style=\"color:red\">NB: If a quote only contains catalogue items, do not send to production unless the items are attached to pipes that need to be produced.</p>\r\n\r\nNote: You can check whether a quote has been sent to production by using the <em>Responses</em> tab next to the Quote Details.\r\n\r\n![set_client.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/885/c60/5ef885c606362088390926.jpg)','<p>A quote can be sent into production from the Front End.</p>\n<p>New: Only quotes that belong to Client can be sent to production. </p>\n<p>How:</p>\n<ul>\n<li>Set up new Client if it does not exist </li>\n<li>Go to the back end to find the Quote</li>\n<li><strong>Link the Client to the Quote</strong> (You will not be able to send to production if you skip this step)</li>\n<li>Then go back to the frond end and you will be able to send to production</li>\n<li>If account has been blocked you will not be able to send to production</li>\n</ul>\n<p style=\"color:red\">NB: If a quote only contains catalogue items, do not send to production unless the items are attached to pipes that need to be produced.</p>\n<p>Note: You can check whether a quote has been sent to production by using the <em>Responses</em> tab next to the Quote Details.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/885/c60/5ef885c606362088390926.jpg\" alt=\"set_client.JPG\" /></p>','2020-06-28 13:58:28',1,'2020-06-28 13:49:03','2021-08-30 07:29:14',NULL),(11,1,'Blocking a Client','blocking-client','How to block a client','- Finance can now block Client/Account\r\n- All new quotes that belong to the client wont have the option to Send to Production.\r\n- SRN download buttons will be disabled.\r\n\r\n\r\n\r\n![cleint_block.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/889/969/5ef8899693675674862108.jpg)\r\n\r\n\r\n\r\n![quote_block.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/889/ac1/5ef889ac1e298366710464.jpg)\r\n\r\n\r\n\r\n![srn_block.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/889/c33/5ef889c335dc2672036776.jpg)','<ul>\n<li>Finance can now block Client/Account</li>\n<li>All new quotes that belong to the client wont have the option to Send to Production.</li>\n<li>SRN download buttons will be disabled.</li>\n</ul>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/889/969/5ef8899693675674862108.jpg\" alt=\"cleint_block.JPG\" /></p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/889/ac1/5ef889ac1e298366710464.jpg\" alt=\"quote_block.JPG\" /></p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/889/c33/5ef889c335dc2672036776.jpg\" alt=\"srn_block.JPG\" /></p>','2020-06-28 14:15:30',1,'2020-06-28 14:13:41','2021-08-30 07:25:09',NULL),(12,1,'Account limit usage','account-limit-usage','Account usage','- Limit usage is calculated from the invoices (Invoice Tracker) amount - payment (payment Tracker)\r\n\r\n\r\n\r\n![limit_usage.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/890/738/5ef8907380d49791618052.jpg)\r\n\r\n\r\n\r\n![account.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/891/07c/5ef89107ce798854955107.jpg)','<ul>\n<li>Limit usage is calculated from the invoices (Invoice Tracker) amount - payment (payment Tracker)</li>\n</ul>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/890/738/5ef8907380d49791618052.jpg\" alt=\"limit_usage.JPG\" /></p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/891/07c/5ef89107ce798854955107.jpg\" alt=\"account.JPG\" /></p>','2020-06-28 14:47:39',1,'2020-06-28 14:46:28','2021-08-30 07:30:20',NULL),(13,1,'How to upload a new help topic','how-upload-new-help-topic','How to upload a new help topic','Step 1: \r\n\r\nGo to blog Tab at the back end: [http://bailaerp.bt-industrial.co.za/backend/rainlab/blog](http://)\r\n\r\nStep 2: \r\n\r\nClick on link Left \"Post\" tab or \"New Post\" button.\r\n\r\nStep 3:\r\n\r\nWrite your content:\r\n\r\nStep 4:\r\nSelect categories \r\n\r\n\r\n\r\n\r\n![blog.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/b1a/de7/5efb1ade7d675825336332.jpg)','<p>Step 1: </p>\n<p>Go to blog Tab at the back end: <a href=\"http://\">http://bailaerp.bt-industrial.co.za/backend/rainlab/blog</a></p>\n<p>Step 2: </p>\n<p>Click on link Left &quot;Post&quot; tab or &quot;New Post&quot; button.</p>\n<p>Step 3:</p>\n<p>Write your content:</p>\n<p>Step 4:\nSelect categories </p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5ef/b1a/de7/5efb1ade7d675825336332.jpg\" alt=\"blog.JPG\" /></p>','2020-06-30 13:01:47',1,'2020-06-30 12:59:00','2020-07-12 20:33:58',NULL),(14,25,'How to Get and upload a Quote','how-get-and-upload-quote','','Step 1:\r\n\r\nNavigate to the \"Sales\" Tab on the Top menu bar, then click on \"New Quote\" under \"Sales\". See image below.\r\n\r\n\r\n\r\n![Step 1.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/af9/369/5f0af93691704546533270.png)\r\n\r\n\r\nStep 2:\r\n\r\nA \"New Quote\" pop up form will appear on the right hand side. Ensure validated, accurate data about order recieved is entered. The ERP will automatically calculate the quote and format it accordingly. See image below. \r\n\r\n\r\n\r\n![Step 2 .png](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/af9/530/5f0af95306278732852942.png)\r\n\r\n\r\nStep 3:\r\n\r\nEnsure that the \"Include VAT\" check box is clicked under \"Quote Items\". See image below.\r\n\r\n\r\n\r\n\r\n![VAT2.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/afc/413/5f0afc413b334188376118.png)\r\n\r\n\r\n\r\nStep 4:\r\n\r\nAfter you have entered valid data on order, click on \"Submit Qoute\" button. See image below.\r\n\r\n\r\n\r\n![Step 3.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b40/3db/5f0b403dbd15f425721908.png)','<p>Step 1:</p>\n<p>Navigate to the &quot;Sales&quot; Tab on the Top menu bar, then click on &quot;New Quote&quot; under &quot;Sales&quot;. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/af9/369/5f0af93691704546533270.png\" alt=\"Step 1.PNG\" /></p>\n<p>Step 2:</p>\n<p>A &quot;New Quote&quot; pop up form will appear on the right hand side. Ensure validated, accurate data about order recieved is entered. The ERP will automatically calculate the quote and format it accordingly. See image below. </p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/af9/530/5f0af95306278732852942.png\" alt=\"Step 2 .png\" /></p>\n<p>Step 3:</p>\n<p>Ensure that the &quot;Include VAT&quot; check box is clicked under &quot;Quote Items&quot;. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/afc/413/5f0afc413b334188376118.png\" alt=\"VAT2.PNG\" /></p>\n<p>Step 4:</p>\n<p>After you have entered valid data on order, click on &quot;Submit Qoute&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b40/3db/5f0b403dbd15f425721908.png\" alt=\"Step 3.PNG\" /></p>','2020-07-12 18:56:23',1,'2020-07-12 18:56:51','2021-08-30 07:32:50',NULL),(15,25,'Delivery Schedules','delivery-schedules','','Navigate to \"Sales\" marked as \"1\", then \"Delivery Schedule\" marked \"2\" on image below.\r\n\r\n\r\n\r\n\r\n![ScheduleB.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b42/08d/5f0b4208dd412587907223.png)\r\n\r\n\r\n\r\n\r\n\r\n**New Delivery Plan.**\r\n\r\nStep 1: \r\n\r\nClick on the \"New Delivery Plan\" button. See image below..\r\n\r\n\r\n\r\n![AND1.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b42/308/5f0b42308cd8e562214464.png)\r\n\r\n\r\n\r\nStep 2: \r\nEnter all related and validated data required on \"New Delivery Plan\" form, then click the \"Save and Close\" button.\r\n\r\n\r\n\r\n![AND2.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b42/442/5f0b42442c4c2041430757.png)\r\n\r\n\r\n\r\n\r\n-- **Deleting a Delivery Plan.**\r\n\r\nStep 1: Select the check box in front of the ID of any entries you\'d like to delete from the \"Schedule Delivery\" database. Then Click the \"Delete Selected\" button. See Image Below.\r\n\r\n\r\n\r\n![DLT.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b42/571/5f0b42571252d863123018.png)','<p>Navigate to &quot;Sales&quot; marked as &quot;1&quot;, then &quot;Delivery Schedule&quot; marked &quot;2&quot; on image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b42/08d/5f0b4208dd412587907223.png\" alt=\"ScheduleB.PNG\" /></p>\n<p><strong>New Delivery Plan.</strong></p>\n<p>Step 1: </p>\n<p>Click on the &quot;New Delivery Plan&quot; button. See image below..</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b42/308/5f0b42308cd8e562214464.png\" alt=\"AND1.PNG\" /></p>\n<p>Step 2:\nEnter all related and validated data required on &quot;New Delivery Plan&quot; form, then click the &quot;Save and Close&quot; button.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b42/442/5f0b42442c4c2041430757.png\" alt=\"AND2.PNG\" /></p>\n<p>-- <strong>Deleting a Delivery Plan.</strong></p>\n<p>Step 1: Select the check box in front of the ID of any entries you\'d like to delete from the &quot;Schedule Delivery&quot; database. Then Click the &quot;Delete Selected&quot; button. See Image Below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b42/571/5f0b42571252d863123018.png\" alt=\"DLT.PNG\" /></p>','2020-07-12 19:04:37',1,'2020-07-12 19:04:41','2021-08-30 08:29:48',NULL),(16,25,'Job Cards','job-cards','','**Creating a new Job Card**.\r\n\r\nStep 1:\r\n\r\nNavigate an click on the \"Production\" Tab on the top menu, then on the \"Job Card\" tab on the left hand side marked with a red dot. See image below.\r\n\r\n\r\n\r\n![A.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b4b/86a/5f0b4b86a39ba503982357.png)\r\n\r\n\r\nStep 2: Click on the \"New Record\" button. see image Below.\r\n\r\n\r\n\r\n![B.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b4b/d80/5f0b4bd809c45216438975.png)\r\n\r\n\r\nStep 3:\r\n\r\nA Create Job card form will pop up. The job cards that can be created must be linked to an existing quote record. select the quote in the \"Pipe In Quote for production\" drop box. see image below.\r\n\r\n\r\n\r\n![InkedC_LI.jpg](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b4e/8fc/5f0b4e8fc286c502582992.jpg)\r\n\r\n\r\nStep 4:\r\n\r\nAt the bottum of the form there are tabs, eg (Changeover part, machine parameters, barrel zone) where You can add details for a more descriptive job card. see image below.\r\n\r\n![D.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b4e/e0c/5f0b4ee0c420d588867387.png)\r\n\r\nStep 5:\r\n\r\nWhen All necessary input boxes have been entered click on the \"Save\" button to save and the job cards will be shared with related parties.\r\n\r\n\r\n\r\n![E.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b51/8c2/5f0b518c231b0469297222.png)','<p><strong>Creating a new Job Card</strong>.</p>\n<p>Step 1:</p>\n<p>Navigate an click on the &quot;Production&quot; Tab on the top menu, then on the &quot;Job Card&quot; tab on the left hand side marked with a red dot. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b4b/86a/5f0b4b86a39ba503982357.png\" alt=\"A.PNG\" /></p>\n<p>Step 2: Click on the &quot;New Record&quot; button. see image Below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b4b/d80/5f0b4bd809c45216438975.png\" alt=\"B.PNG\" /></p>\n<p>Step 3:</p>\n<p>A Create Job card form will pop up. The job cards that can be created must be linked to an existing quote record. select the quote in the &quot;Pipe In Quote for production&quot; drop box. see image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b4e/8fc/5f0b4e8fc286c502582992.jpg\" alt=\"InkedC_LI.jpg\" /></p>\n<p>Step 4:</p>\n<p>At the bottum of the form there are tabs, eg (Changeover part, machine parameters, barrel zone) where You can add details for a more descriptive job card. see image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b4e/e0c/5f0b4ee0c420d588867387.png\" alt=\"D.PNG\" /></p>\n<p>Step 5:</p>\n<p>When All necessary input boxes have been entered click on the &quot;Save&quot; button to save and the job cards will be shared with related parties.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b51/8c2/5f0b518c231b0469297222.png\" alt=\"E.PNG\" /></p>','2020-07-12 23:00:00',1,'2020-07-12 20:08:19','2020-07-14 23:09:42',NULL),(17,25,'Purchase Raw Material','purchase-raw-material','','**Purchasing Raw Material**:\r\n\r\nStep 1:\r\n\r\nNavigate to the \"Raw Material\" Tab marked 1 on the top menu, and then \"Purchase Raw Material\" marked 2 on the left hand side. See image below.\r\n\r\n\r\n\r\n![A.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b56/3d6/5f0b563d6aeda382375947.png)\r\n\r\n\r\n\r\nStep 2:\r\n\r\nThen enter the purchse request on the pop up form \"Create Purchase\". then click \"Create and Close\" button.','<p><strong>Purchasing Raw Material</strong>:</p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;Raw Material&quot; Tab marked 1 on the top menu, and then &quot;Purchase Raw Material&quot; marked 2 on the left hand side. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/b56/3d6/5f0b563d6aeda382375947.png\" alt=\"A.PNG\" /></p>\n<p>Step 2:</p>\n<p>Then enter the purchse request on the pop up form &quot;Create Purchase&quot;. then click &quot;Create and Close&quot; button.</p>','2020-07-12 23:00:00',1,'2020-07-12 20:32:18','2020-07-14 23:10:19',NULL),(18,25,'Tools/Checklist','toolschecklist','','**Tools and check list**.\r\n\r\nStep 1:\r\n\r\nNavigate to the \"Maintenance\" tab marked 1 on the top menu, then \"Tools/Checklist\" tab on the left menu. All data on tools, check list and maintenance schedules are datialed on this form. see image below.\r\n\r\n\r\n![Main.png](https://bailaerp.bt-industrial.co.za/storage/app/media/uploaded-files/Main.png)\r\n\r\nStep 2:\r\n\r\nTo create a maintenance checklist, first make sure that you have the tools or equpment that will be maintained. To do that, navigate to Equpment/Tools, add the new equpment if one isn\'t available.\r\n\r\n![Main2.png](https://bailaerp.bt-industrial.co.za/storage/app/media/uploaded-files/Main2.png)\r\n\r\nStep 3:\r\n\r\nGo to Checklist Setup. In there, create a new checklist with instruction. Afterwards, you create Checkpoints within that checklist entry and specify what needs to be checked (eg. Baila 1, Baila 2, Baila 3).  Do not forget to assign the check point with the number 0.\r\n\r\n\r\n![Main3.png](https://bailaerp.bt-industrial.co.za/storage/app/media/uploaded-files/Main3.png)','<p><strong>Tools and check list</strong>.</p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;Maintenance&quot; tab marked 1 on the top menu, then &quot;Tools/Checklist&quot; tab on the left menu. All data on tools, check list and maintenance schedules are datialed on this form. see image below.</p>\n<p><img src=\"https://bailaerp.bt-industrial.co.za/storage/app/media/uploaded-files/Main.png\" alt=\"Main.png\" /></p>\n<p>Step 2:</p>\n<p>To create a maintenance checklist, first make sure that you have the tools or equpment that will be maintained. To do that, navigate to Equpment/Tools, add the new equpment if one isn\'t available.</p>\n<p><img src=\"https://bailaerp.bt-industrial.co.za/storage/app/media/uploaded-files/Main2.png\" alt=\"Main2.png\" /></p>\n<p>Step 3:</p>\n<p>Go to Checklist Setup. In there, create a new checklist with instruction. Afterwards, you create Checkpoints within that checklist entry and specify what needs to be checked (eg. Baila 1, Baila 2, Baila 3).  Do not forget to assign the check point with the number 0.</p>\n<p><img src=\"https://bailaerp.bt-industrial.co.za/storage/app/media/uploaded-files/Main3.png\" alt=\"Main3.png\" /></p>','2020-07-12 23:00:00',1,'2020-07-12 20:46:56','2021-08-30 09:17:33',NULL),(19,25,'Return Note','return-note','','**Creating A Return Note**:\r\n\r\nStep 1:\r\n\r\nNavigate to the \"Sales\" tab on marked 1 the top menu, then \"SRN/Delivery\" marked 2 on the left menu. Select a record you wou would like to create a Return Note for on this now appearing database. See image below.\r\n\r\n\r\n![A.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cb7/3d2/5f0cb73d21276938730092.png)\r\n\r\n\r\n\r\nStep 2:\r\n\r\nTo insert a return note record, under the \"SRN SetUp\" click on the \"Return Note\" tab marked in red. See image below.\r\n\r\n\r\n\r\n![B.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cb8/51e/5f0cb851eb95f365582455.png)\r\n\r\nStep 3:\r\n\r\nThe Return Note records will be located on this page. To Create a Return Note click on the \"Create Return Note\" button. See image below.\r\n\r\n\r\n\r\n![C.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cb9/530/5f0cb95305804746450423.png)\r\n\r\nStep 4:\r\n\r\nOn this \"Create Return Note\" form, you will only be permitted to create return notes for already existing quote records. Select a record under the \"Pipe/Product Item\" drop box. The returnable number of units are limited to the number of units in the quote record. A client can not return more products than purchased. Please enter all relative and validated data in this form, then click the \"Create\" button. See image below.\r\n\r\n\r\n\r\n![D.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cbb/9d9/5f0cbb9d909a3653074962.png)','<p><strong>Creating A Return Note</strong>:</p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;Sales&quot; tab on marked 1 the top menu, then &quot;SRN/Delivery&quot; marked 2 on the left menu. Select a record you wou would like to create a Return Note for on this now appearing database. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cb7/3d2/5f0cb73d21276938730092.png\" alt=\"A.PNG\" /></p>\n<p>Step 2:</p>\n<p>To insert a return note record, under the &quot;SRN SetUp&quot; click on the &quot;Return Note&quot; tab marked in red. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cb8/51e/5f0cb851eb95f365582455.png\" alt=\"B.PNG\" /></p>\n<p>Step 3:</p>\n<p>The Return Note records will be located on this page. To Create a Return Note click on the &quot;Create Return Note&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cb9/530/5f0cb95305804746450423.png\" alt=\"C.PNG\" /></p>\n<p>Step 4:</p>\n<p>On this &quot;Create Return Note&quot; form, you will only be permitted to create return notes for already existing quote records. Select a record under the &quot;Pipe/Product Item&quot; drop box. The returnable number of units are limited to the number of units in the quote record. A client can not return more products than purchased. Please enter all relative and validated data in this form, then click the &quot;Create&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cbb/9d9/5f0cbb9d909a3653074962.png\" alt=\"D.PNG\" /></p>','2020-07-13 23:00:00',1,'2020-07-12 21:14:57','2020-07-14 23:07:06',NULL),(20,25,'Accessing Raw Material Suppliers','accessing-raw-material-suppliers','','**Suppliers**:\r\n\r\n\r\nStep 1:\r\n\r\nNavigate and click on the \"Raw Material\" tab marked 1 on the top menu. Then navigate and click on the \"Suppliers\" tab marked 2 on the left hand side menu. The table on the pop up form shows all stored supplier info for raw material. See image below.\r\n\r\n\r\n\r\n![A2.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/c1a/6d9/5f0c1a6d9a207869452124.png)\r\n\r\n\r\n\r\n**Entering a New supplier to the Supplier database**.\r\n\r\nStep 1;\r\n\r\nClick on the \"New Supplier\" button to Enter a new supplier detials. See image below.\r\n\r\n\r\n\r\n![Add.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/c1e/4b2/5f0c1e4b28059851667680.png)\r\n\r\n\r\nStep 2:\r\n\r\n A \"Create Supplier\" form will appear on the main screen. PLease enter correct validated data. When done entering the supplier data click on the \"Create and Close\" button. See image below.\r\n \r\n \r\n\r\n![InkedAdd2_LI.jpg](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/c20/605/5f0c206052ac6799111109.jpg)\r\n\r\n**Deleting an existing supplier record**.\r\n\r\nStep 1:\r\n\r\nOn The \"Suppliers\" tab. Click on the check box next to the supplier/s you wish to delete, then click on the \"Delete Selected\" button. The supplier selecte will be deleted. See image below.\r\n\r\n\r\n\r\n![DLT2.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/c21/e46/5f0c21e466222184588996.png)','<p><strong>Suppliers</strong>:</p>\n<p>Step 1:</p>\n<p>Navigate and click on the &quot;Raw Material&quot; tab marked 1 on the top menu. Then navigate and click on the &quot;Suppliers&quot; tab marked 2 on the left hand side menu. The table on the pop up form shows all stored supplier info for raw material. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/c1a/6d9/5f0c1a6d9a207869452124.png\" alt=\"A2.PNG\" /></p>\n<p><strong>Entering a New supplier to the Supplier database</strong>.</p>\n<p>Step 1;</p>\n<p>Click on the &quot;New Supplier&quot; button to Enter a new supplier detials. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/c1e/4b2/5f0c1e4b28059851667680.png\" alt=\"Add.PNG\" /></p>\n<p>Step 2:</p>\n<p>A &quot;Create Supplier&quot; form will appear on the main screen. PLease enter correct validated data. When done entering the supplier data click on the &quot;Create and Close&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/c20/605/5f0c206052ac6799111109.jpg\" alt=\"InkedAdd2_LI.jpg\" /></p>\n<p><strong>Deleting an existing supplier record</strong>.</p>\n<p>Step 1:</p>\n<p>On The &quot;Suppliers&quot; tab. Click on the check box next to the supplier/s you wish to delete, then click on the &quot;Delete Selected&quot; button. The supplier selecte will be deleted. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/c21/e46/5f0c21e466222184588996.png\" alt=\"DLT2.PNG\" /></p>','2020-07-13 14:00:00',1,'2020-07-13 10:58:34','2020-07-14 23:08:56',NULL),(21,25,'Alter The DataBase fields','alter-database-fields','','**Choosing which fields of the database you would like to see appear on the opened table**.\r\n\r\nStep 1:\r\n\r\nOpen a database of your choice. Click on the icon On the top right hand corner of the database. See image below.\r\n\r\n\r\n\r\n\r\n\r\n![Filter.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cb3/1b7/5f0cb31b7f240720911086.png)\r\n\r\n\r\nStep 2: \r\n\r\nUse the check boxes to choose which fields you would like to see on the database table, then click the \"Apply\" button. See image below.\r\n\r\n\r\n\r\n![Filter 2.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cb3/770/5f0cb3770b5f9259340391.png)','<p><strong>Choosing which fields of the database you would like to see appear on the opened table</strong>.</p>\n<p>Step 1:</p>\n<p>Open a database of your choice. Click on the icon On the top right hand corner of the database. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cb3/1b7/5f0cb31b7f240720911086.png\" alt=\"Filter.PNG\" /></p>\n<p>Step 2: </p>\n<p>Use the check boxes to choose which fields you would like to see on the database table, then click the &quot;Apply&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cb3/770/5f0cb3770b5f9259340391.png\" alt=\"Filter 2.PNG\" /></p>','2020-07-13 23:00:00',1,'2020-07-13 21:20:47','2020-07-13 21:23:55',NULL),(22,25,'Searching A Database','searching-database','','**Searching or filtering a database using key words**:\r\n\r\nStep 1:\r\n\r\nTo use a key word to search or filter a database. Navigate to the text box with a search icon on the top right hand corner of your current form. This function will search through each field and record, to find matching database inputs. See image below.\r\n\r\n\r\n![InkedSearching_LI.jpg](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cbf/740/5f0cbf740dcef329902626.jpg)','<p><strong>Searching or filtering a database using key words</strong>:</p>\n<p>Step 1:</p>\n<p>To use a key word to search or filter a database. Navigate to the text box with a search icon on the top right hand corner of your current form. This function will search through each field and record, to find matching database inputs. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cbf/740/5f0cbf740dcef329902626.jpg\" alt=\"InkedSearching_LI.jpg\" /></p>','2020-07-13 23:00:00',1,'2020-07-13 22:14:20','2020-07-13 22:14:20',NULL),(23,25,'Scrap Codes','scrap-codes','','Step 1:\r\n\r\nNavigate to the \"Production\" tab on the top menu marked \"1\", then Navigate to the \"Scrap Codes\" tab on the left hand side menu marked \"2\". A database of all scrap Codes will appear on this page. See image below.\r\n\r\n![A.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cc1/c7c/5f0cc1c7c32aa317648969.png)\r\n\r\n\r\n**Adding a scrap code record:**\r\n\r\nStep 1:\r\n\r\nOn the \"Scrap Codes\" page click on the \"New Scrap Code\" button, to bring out the \"New Scrap Code\" form. See image below.\r\n\r\n\r\n![New.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cc4/12b/5f0cc412b509e897758665.png)\r\n\r\nStep 2:\r\n\r\nOn this form enter the data of Scrap Codes, And click the \"Close\" butto to save and close form. See image below.\r\n\r\n![New2.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cc4/725/5f0cc4725a640056710785.png)\r\n\r\n\r\n**Deleting a \"Scrap Codes\" record:**\r\n\r\nClick on the check box next to the \"ID\" field to select a record you wish to delete, then click on the \"Delete Selected\" button.\r\n\r\n![Delete.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cc2/de4/5f0cc2de4e38d765371066.png)','<p>Step 1:</p>\n<p>Navigate to the &quot;Production&quot; tab on the top menu marked &quot;1&quot;, then Navigate to the &quot;Scrap Codes&quot; tab on the left hand side menu marked &quot;2&quot;. A database of all scrap Codes will appear on this page. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cc1/c7c/5f0cc1c7c32aa317648969.png\" alt=\"A.PNG\" /></p>\n<p><strong>Adding a scrap code record:</strong></p>\n<p>Step 1:</p>\n<p>On the &quot;Scrap Codes&quot; page click on the &quot;New Scrap Code&quot; button, to bring out the &quot;New Scrap Code&quot; form. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cc4/12b/5f0cc412b509e897758665.png\" alt=\"New.PNG\" /></p>\n<p>Step 2:</p>\n<p>On this form enter the data of Scrap Codes, And click the &quot;Close&quot; butto to save and close form. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cc4/725/5f0cc4725a640056710785.png\" alt=\"New2.PNG\" /></p>\n<p><strong>Deleting a &quot;Scrap Codes&quot; record:</strong></p>\n<p>Click on the check box next to the &quot;ID&quot; field to select a record you wish to delete, then click on the &quot;Delete Selected&quot; button.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cc2/de4/5f0cc2de4e38d765371066.png\" alt=\"Delete.PNG\" /></p>','2020-07-13 23:00:00',1,'2020-07-13 22:32:05','2020-07-14 23:08:18',NULL),(24,25,'Schedules and Job Cards','schedules-and-job-cards','','**Accessing Maintenance Schedules and Job Cards.**\r\n\r\nStep 1:\r\n\r\nNavigate to the \"Maintenace\" tab Marked \"1\" on the top menu, then Navigate to the \"Schedule/Job Cards\" tab Marked \"2\" on the left hand side menu. See image below.\r\n\r\n\r\n![A.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cc8/736/5f0cc8736bfe6786966204.png)\r\n\r\n\r\n**Schedules:**\r\n\r\nStep 1:\r\n\r\nTo view and upload schedules click on the \"Schedule\" button.\r\n\r\nStep 2:\r\n\r\nThis current form shows all schedules of maintenance. And to enter new scheedule click on the \"New Schedule\" button. See immage below.\r\n\r\n![New Schedule.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/ccb/319/5f0ccb31961a5065458933.png)\r\n\r\nStep 3:\r\n\r\nOn the \"Create Schedule\" form enter the next schedule to be entered on the database then click on the \"Create And Close\" button to save entry.\r\n\r\n\r\n![Schedule form.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/ccc/8da/5f0ccc8da10c5103265329.png)','<p><strong>Accessing Maintenance Schedules and Job Cards.</strong></p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;Maintenace&quot; tab Marked &quot;1&quot; on the top menu, then Navigate to the &quot;Schedule/Job Cards&quot; tab Marked &quot;2&quot; on the left hand side menu. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/cc8/736/5f0cc8736bfe6786966204.png\" alt=\"A.PNG\" /></p>\n<p><strong>Schedules:</strong></p>\n<p>Step 1:</p>\n<p>To view and upload schedules click on the &quot;Schedule&quot; button.</p>\n<p>Step 2:</p>\n<p>This current form shows all schedules of maintenance. And to enter new scheedule click on the &quot;New Schedule&quot; button. See immage below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/ccb/319/5f0ccb31961a5065458933.png\" alt=\"New Schedule.PNG\" /></p>\n<p>Step 3:</p>\n<p>On the &quot;Create Schedule&quot; form enter the next schedule to be entered on the database then click on the &quot;Create And Close&quot; button to save entry.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/ccc/8da/5f0ccc8da10c5103265329.png\" alt=\"Schedule form.PNG\" /></p>','2020-07-13 23:30:00',1,'2020-07-13 23:07:41','2020-07-14 23:05:57',NULL),(25,25,'Upcoming Maintenance','upcoming-maintenance','','Step 1:\r\n\r\nNavigate and click on the \"Maintenance\" tab marked \"1\" on the top menu, then Navigate and click on the \"Upcoming Maintenance\" on the left menu. The table on this page displays all upcoming maintenance stored in a database, see image below.\r\n\r\n\r\n![Upcoming .PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e1c/987/5f0e1c987c833940772668.png)','<p>Step 1:</p>\n<p>Navigate and click on the &quot;Maintenance&quot; tab marked &quot;1&quot; on the top menu, then Navigate and click on the &quot;Upcoming Maintenance&quot; on the left menu. The table on this page displays all upcoming maintenance stored in a database, see image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e1c/987/5f0e1c987c833940772668.png\" alt=\"Upcoming .PNG\" /></p>','2020-07-14 23:58:00',1,'2020-07-14 23:05:16','2020-07-14 23:05:16',NULL),(26,25,'Vendors','vendors','','**Accessiing the Vendor\'s database\"**\r\n\r\nStep 1:\r\n\r\nNavigate and click on the \"Maintenance\" tab marked \"1\" on top menu, then Navigate and click on the \"Vendors\" tab marked \"2\" on the left hand side menu. The table that will appear on the main screen contains the vendor\'s records. See image below.\r\n\r\n\r\n\r\n![A.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e24/069/5f0e240698593121677702.png)\r\n\r\n**Adding A New Vendor:**\r\n\r\nStep 1:\r\n\r\nClick on the \"New Vendor\" button. See image below.\r\n\r\n\r\n![New.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e25/9cb/5f0e259cba52d342729880.png)\r\n\r\nStep 2:\r\n\r\nOn the \"Create Vendor\" form enter all required data on new vendor, Then click the \"Close\" button at the bottom of the screen.\r\n\r\n\r\n![New2.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e26/5b4/5f0e265b43866164327442.png)\r\n\r\n\r\n**Setup Vendor Types:**\r\n\r\nStep 1:\r\n\r\nOn the \"Vendors\" tab, click on the \"Setup Vendor Type\" button. See image below.\r\n\r\n\r\n\r\n![Set Up vendor.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e27/deb/5f0e27debb903030398949.png)\r\n\r\n\r\nStep 2:\r\n\r\nClick on the \"New Vendor Type\" button. See image below.\r\n\r\n![New Vendor 3.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e28/988/5f0e28988f45f335210402.png)\r\n\r\nStep 3:\r\n\r\nEnter new vendor type in the \"Type\" text box, then click on the \"Close\" button. See image below.\r\n\r\n\r\n![New vendor 4.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e29/77b/5f0e2977b7ac2447900097.png)\r\n\r\n**Deleting a vendor record:**\r\n\r\nStep 1:\r\n\r\nOn the \"Setup Vendor Type\" form. Tick on the check box next to the \"ID\" field to select a record you wish to delete, then click on the \"Delete\" button. See image below.\r\n\r\n\r\n![Delete Vendor.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e2a/2c3/5f0e2a2c302f0077866653.png)','<p><strong>Accessiing the Vendor\'s database&quot;</strong></p>\n<p>Step 1:</p>\n<p>Navigate and click on the &quot;Maintenance&quot; tab marked &quot;1&quot; on top menu, then Navigate and click on the &quot;Vendors&quot; tab marked &quot;2&quot; on the left hand side menu. The table that will appear on the main screen contains the vendor\'s records. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e24/069/5f0e240698593121677702.png\" alt=\"A.PNG\" /></p>\n<p><strong>Adding A New Vendor:</strong></p>\n<p>Step 1:</p>\n<p>Click on the &quot;New Vendor&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e25/9cb/5f0e259cba52d342729880.png\" alt=\"New.PNG\" /></p>\n<p>Step 2:</p>\n<p>On the &quot;Create Vendor&quot; form enter all required data on new vendor, Then click the &quot;Close&quot; button at the bottom of the screen.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e26/5b4/5f0e265b43866164327442.png\" alt=\"New2.PNG\" /></p>\n<p><strong>Setup Vendor Types:</strong></p>\n<p>Step 1:</p>\n<p>On the &quot;Vendors&quot; tab, click on the &quot;Setup Vendor Type&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e27/deb/5f0e27debb903030398949.png\" alt=\"Set Up vendor.PNG\" /></p>\n<p>Step 2:</p>\n<p>Click on the &quot;New Vendor Type&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e28/988/5f0e28988f45f335210402.png\" alt=\"New Vendor 3.PNG\" /></p>\n<p>Step 3:</p>\n<p>Enter new vendor type in the &quot;Type&quot; text box, then click on the &quot;Close&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e29/77b/5f0e2977b7ac2447900097.png\" alt=\"New vendor 4.PNG\" /></p>\n<p><strong>Deleting a vendor record:</strong></p>\n<p>Step 1:</p>\n<p>On the &quot;Setup Vendor Type&quot; form. Tick on the check box next to the &quot;ID&quot; field to select a record you wish to delete, then click on the &quot;Delete&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/e2a/2c3/5f0e2a2c302f0077866653.png\" alt=\"Delete Vendor.PNG\" /></p>','2020-07-15 00:58:00',1,'2020-07-15 00:00:08','2020-07-15 00:00:08',NULL),(27,25,'Help Function','help-function','','**Navigating around the User Guide PDF:**\r\n\r\nStep 1:\r\n\r\nClick on the \"Help\" button on the top right hand side of the top menu. See image below.\r\n\r\n\r\n\r\n![Help 1.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/f67/44e/5f0f6744ef9fd307086136.png)\r\n\r\n\r\nStep 2:\r\n\r\nScroll to the \"Table of Content\". On the Table Of Content you can click on any subtitle of interest, and the pdf will jump to the page that contains the subtitle content. See image below.\r\n\r\n\r\n![TC.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/f68/f37/5f0f68f374853745893997.png)','<p><strong>Navigating around the User Guide PDF:</strong></p>\n<p>Step 1:</p>\n<p>Click on the &quot;Help&quot; button on the top right hand side of the top menu. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/f67/44e/5f0f6744ef9fd307086136.png\" alt=\"Help 1.PNG\" /></p>\n<p>Step 2:</p>\n<p>Scroll to the &quot;Table of Content&quot;. On the Table Of Content you can click on any subtitle of interest, and the pdf will jump to the page that contains the subtitle content. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f0/f68/f37/5f0f68f374853745893997.png\" alt=\"TC.PNG\" /></p>','2020-07-15 23:00:00',1,'2020-07-15 22:42:07','2020-07-15 22:42:07',NULL),(28,25,'Generate A Data Pack','generate-data-pack','','**How to generate a Data Pack:**\r\n\r\nStep 1:\r\n\r\nNavigate to the \"QC\" tab marked \"1\" on the top menu, then \"Data Pack\" marked \"2\" on the left hand side menu. On the pop form that will appear on the main screen select a record you would like to access. See image below.\r\n\r\n\r\n![DataPack.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/562/6ed/5f15626edc403860970079.png)\r\n\r\nStep 2: \r\n\r\nBefore clicking the download data pack button, you need to do as follows. You need to click on the buttons next to the (\"Letter Head\",\"COC\",\"Photos\") marked with red marking on them.And the titles have a \"Run First\" caption next to them. See image below.\r\n\r\n\r\n![Run first.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/56d/b73/5f156db73e401611152805.png)\r\n\r\n\r\nStep 3:\r\n\r\nAfter running and generating the documents on the previous step, you can now click on the \"Download\" Data Pack button. See image below.\r\n\r\n\r\n\r\n![last step.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/56f/269/5f156f269030e623312218.png)','<p><strong>How to generate a Data Pack:</strong></p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;QC&quot; tab marked &quot;1&quot; on the top menu, then &quot;Data Pack&quot; marked &quot;2&quot; on the left hand side menu. On the pop form that will appear on the main screen select a record you would like to access. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/562/6ed/5f15626edc403860970079.png\" alt=\"DataPack.PNG\" /></p>\n<p>Step 2: </p>\n<p>Before clicking the download data pack button, you need to do as follows. You need to click on the buttons next to the (&quot;Letter Head&quot;,&quot;COC&quot;,&quot;Photos&quot;) marked with red marking on them.And the titles have a &quot;Run First&quot; caption next to them. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/56d/b73/5f156db73e401611152805.png\" alt=\"Run first.PNG\" /></p>\n<p>Step 3:</p>\n<p>After running and generating the documents on the previous step, you can now click on the &quot;Download&quot; Data Pack button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/56f/269/5f156f269030e623312218.png\" alt=\"last step.PNG\" /></p>','2020-07-20 23:00:00',1,'2020-07-20 12:22:53','2020-07-20 12:22:53',NULL),(29,25,'Uploading a Task','uploading-task','','**Uploading a task/request for the IT department:**\r\n\r\nStep 1:\r\n\r\nNavigate to the \"Task\" tab on the top menu marked \'1\'. On the main screen you will see a database containing requests to the IT support team, And the task completion statuses. On this form you can add a task/request to the IT support team by clicking on the \"New Task\" button marked \'2\'. See image below.\r\n\r\n\r\n![Task.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/5f8/ec6/5f15f8ec6006d565457780.png)\r\n\r\n\r\nStep 2:\r\n\r\nOn the \"Create Task\" form provide all required data to to be attended to, please be as descriptive as possible. See image 2.1. Then click on the \"Files\" tab to upload files or pictures to  aid the team with your request, see image 2.2 below.\r\n\r\n\r\n2.1\r\n![Create task.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/5f9/981/5f15f9981aa2e215015221.png)\r\n\r\n2.2\r\n\r\n\r\n![last step.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/5f9/a17/5f15f9a173ae4121704389.png)','<p><strong>Uploading a task/request for the IT department:</strong></p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;Task&quot; tab on the top menu marked \'1\'. On the main screen you will see a database containing requests to the IT support team, And the task completion statuses. On this form you can add a task/request to the IT support team by clicking on the &quot;New Task&quot; button marked \'2\'. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/5f8/ec6/5f15f8ec6006d565457780.png\" alt=\"Task.PNG\" /></p>\n<p>Step 2:</p>\n<p>On the &quot;Create Task&quot; form provide all required data to to be attended to, please be as descriptive as possible. See image 2.1. Then click on the &quot;Files&quot; tab to upload files or pictures to  aid the team with your request, see image 2.2 below.</p>\n<p>2.1\n<img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/5f9/981/5f15f9981aa2e215015221.png\" alt=\"Create task.PNG\" /></p>\n<p>2.2</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/5f9/a17/5f15f9a173ae4121704389.png\" alt=\"last step.PNG\" /></p>','2020-07-15 23:00:00',1,'2020-07-20 22:23:40','2020-07-20 22:24:20',NULL),(30,25,'Control Sheets','control-sheets','','**Accessing Control Sheets:**\r\n\r\n\r\nStep 1:\r\n\r\nNavigate to the \"Production\" tab on the top menu marked \"1\", then click on \"Control Sheet\" on the left hand side menu marked \"2\". You will then see a database containing control sheet records. You can click on the \"Download CS\" button to download a computer generated control sheet of your choice. You can also click on a record to validate/edit data. See image below.\r\n\r\n\r\n![STep 1.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/603/d99/5f1603d99ae50411056685.png)\r\n\r\nStep 2: (Editing a Control Sheet)\r\n\r\nOn the \"Edit Control sheet\" form, you can change or validate the data entered for a each record, See image 2.1. and you can preview the Control sheet before you download and print it, by click on the \"Preview Actuals\" tab to see a pdf format of the control sheet, See image 2.2.\r\n\r\nImage 2.1\r\n![Step 2.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/605/b46/5f1605b46afcc357852916.png)\r\n\r\nImage 2.2\r\n\r\n![CS Preview.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/607/7a6/5f16077a60d81772695197.png)\r\n\r\n\r\nWhen you are satisfied click on the \"Save And Close\" button on the bottom of the page,','<p><strong>Accessing Control Sheets:</strong></p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;Production&quot; tab on the top menu marked &quot;1&quot;, then click on &quot;Control Sheet&quot; on the left hand side menu marked &quot;2&quot;. You will then see a database containing control sheet records. You can click on the &quot;Download CS&quot; button to download a computer generated control sheet of your choice. You can also click on a record to validate/edit data. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/603/d99/5f1603d99ae50411056685.png\" alt=\"STep 1.PNG\" /></p>\n<p>Step 2: (Editing a Control Sheet)</p>\n<p>On the &quot;Edit Control sheet&quot; form, you can change or validate the data entered for a each record, See image 2.1. and you can preview the Control sheet before you download and print it, by click on the &quot;Preview Actuals&quot; tab to see a pdf format of the control sheet, See image 2.2.</p>\n<p>Image 2.1\n<img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/605/b46/5f1605b46afcc357852916.png\" alt=\"Step 2.PNG\" /></p>\n<p>Image 2.2</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/607/7a6/5f16077a60d81772695197.png\" alt=\"CS Preview.PNG\" /></p>\n<p>When you are satisfied click on the &quot;Save And Close&quot; button on the bottom of the page,</p>','2020-07-15 23:00:00',1,'2020-07-20 23:10:04','2020-07-20 23:10:04',NULL),(31,25,'Plant Utilisation Stats','plant-utilisation-stats','','Accessing plant utilisation stats:\r\n\r\nStep 1:\r\n\r\nNavigate to the \"Prodduction\" tab on the top menu marked \"1\", then click on \"Plant Stats\" on the left menu marked \"2\". On this main screen you will see the Bailers represented in the stats, and how much each bailer is capable to produce in Kilograms per hour. To see a graphical representation of the stats, click on the \"Pant Utilisation Stats\" button. See image below.\r\n\r\n\r\n\r\n![Plant Stats ..1  .PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/69d/888/5f169d8882bcc659182735.png)\r\n\r\nStep 2:\r\n\r\nOn this screen you have a graph displaying the plant utilisation stats. The Yellow dotted line shows the maximun plant production potential for a month for all 3 bailers combined. And the black dotted line shows the average production through the months represented on the graph. See image below.\r\n\r\n![Stats.1  .PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/69e/a60/5f169ea602cd9104881540.png)\r\n\r\n\r\nOn the plant utility graph you can click on a on the components under the graph eg (bailer i, bailer ii,bailer iii) to activate which data to show on the graph. And you can click on the 3 horizontal line on the top right hand side to download graph as pdf or view in full screen.','<p>Accessing plant utilisation stats:</p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;Prodduction&quot; tab on the top menu marked &quot;1&quot;, then click on &quot;Plant Stats&quot; on the left menu marked &quot;2&quot;. On this main screen you will see the Bailers represented in the stats, and how much each bailer is capable to produce in Kilograms per hour. To see a graphical representation of the stats, click on the &quot;Pant Utilisation Stats&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/69d/888/5f169d8882bcc659182735.png\" alt=\"Plant Stats ..1  .PNG\" /></p>\n<p>Step 2:</p>\n<p>On this screen you have a graph displaying the plant utilisation stats. The Yellow dotted line shows the maximun plant production potential for a month for all 3 bailers combined. And the black dotted line shows the average production through the months represented on the graph. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/69e/a60/5f169ea602cd9104881540.png\" alt=\"Stats.1  .PNG\" /></p>\n<p>On the plant utility graph you can click on a on the components under the graph eg (bailer i, bailer ii,bailer iii) to activate which data to show on the graph. And you can click on the 3 horizontal line on the top right hand side to download graph as pdf or view in full screen.</p>','2020-07-15 23:00:00',1,'2020-07-21 09:44:06','2020-07-21 10:11:14',NULL),(32,25,'Material Names','material-names','','Step 1:\r\n\r\nNavigate to the \"Raw Material\" on the top menu marked \"1\", then click on the \"Material Names\" on the left hand side marked \"2\". The database shows all materials entered into record. You can change and access more data on each material by clicking on the record. And to add a new material to the database you can click on the \"New Product Name\" button. See image below.\r\n\r\n![step 1.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/6a5/ff8/5f16a5ff83d7f362204629.png)','<p>Step 1:</p>\n<p>Navigate to the &quot;Raw Material&quot; on the top menu marked &quot;1&quot;, then click on the &quot;Material Names&quot; on the left hand side marked &quot;2&quot;. The database shows all materials entered into record. You can change and access more data on each material by clicking on the record. And to add a new material to the database you can click on the &quot;New Product Name&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/6a5/ff8/5f16a5ff83d7f362204629.png\" alt=\"step 1.PNG\" /></p>','2020-07-13 23:00:00',1,'2020-07-21 10:30:39','2020-07-21 10:30:39',NULL),(33,25,'Lab Results','lab-results','','Step 1:\r\n\r\nNavigate to the \"QC\" tab marked \"1\" on the top menu, then click on \"Lab Results\" tab marked \"2\" on the left hand side menu. On this screen you will see a database containing records of lab results conducted on material.you can click on any record on the database to access more detials on a single record. See image below.\r\n\r\n\r\n![LB.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/75f/b37/5f175fb3771b3365370191.png)\r\n\r\n\r\nStep 2:\r\n\r\nOn the \"Edit Lab Result\" form you can edit and access lab test documents on the record you are currently on. The lab result documents and pictures are available in the tabs pointed at by the red arrow. Make sure after all edits you click on the \"Save And Close\" button. See image below.  \r\n\r\n\r\n![Step 2.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/75f/ae7/5f175fae7bbae171058198.png)','<p>Step 1:</p>\n<p>Navigate to the &quot;QC&quot; tab marked &quot;1&quot; on the top menu, then click on &quot;Lab Results&quot; tab marked &quot;2&quot; on the left hand side menu. On this screen you will see a database containing records of lab results conducted on material.you can click on any record on the database to access more detials on a single record. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/75f/b37/5f175fb3771b3365370191.png\" alt=\"LB.PNG\" /></p>\n<p>Step 2:</p>\n<p>On the &quot;Edit Lab Result&quot; form you can edit and access lab test documents on the record you are currently on. The lab result documents and pictures are available in the tabs pointed at by the red arrow. Make sure after all edits you click on the &quot;Save And Close&quot; button. See image below.  </p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/75f/ae7/5f175fae7bbae171058198.png\" alt=\"Step 2.PNG\" /></p>','2020-07-21 23:58:00',1,'2020-07-21 23:46:58','2020-07-21 23:46:58',NULL),(34,25,'Index','index','','Accessing Quality Control Indexs:\r\n\r\nStep 1:\r\n\r\nNavigate to the \"QC\" tab marked \"1\" on the top menu, then click on \"Index\" marked \"2\" on the left hand side menu. The database that will appear on the main screen contains all recorded indexes used in the department of Quality Control. And you can add an index by clicking in the \"New Data Pack Index\". See image below.\r\n\r\n![Step 1.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/763/ae6/5f1763ae6efb4869464725.png)','<p>Accessing Quality Control Indexs:</p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;QC&quot; tab marked &quot;1&quot; on the top menu, then click on &quot;Index&quot; marked &quot;2&quot; on the left hand side menu. The database that will appear on the main screen contains all recorded indexes used in the department of Quality Control. And you can add an index by clicking in the &quot;New Data Pack Index&quot;. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/763/ae6/5f1763ae6efb4869464725.png\" alt=\"Step 1.PNG\" /></p>','2020-07-22 00:20:00',1,'2020-07-21 23:56:59','2020-07-21 23:56:59',NULL),(35,25,'NCR','ncr','','**Accessing Non-Conformance Reports:**\r\n\r\n\r\nStep 1:\r\n\r\nNavigate to the \"QC\" tab marked \"2\" on the top menu, then click on the \"NCR\" tab marked \"2\" on the left hand side the menu. By clicking on a record you can access the NRC posted on this datsbase. See image below.\r\n\r\n![NCR.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/767/7d2/5f17677d2ab3a517748762.png)','<p><strong>Accessing Non-Conformance Reports:</strong></p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;QC&quot; tab marked &quot;2&quot; on the top menu, then click on the &quot;NCR&quot; tab marked &quot;2&quot; on the left hand side the menu. By clicking on a record you can access the NRC posted on this datsbase. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/767/7d2/5f17677d2ab3a517748762.png\" alt=\"NCR.PNG\" /></p>','2020-07-23 00:45:00',1,'2020-07-22 00:12:37','2020-07-22 00:12:37',NULL),(36,25,'Departments and floders','departments-and-floders','','**Accessing Department details and folders:**\r\n\r\nStep 1:\r\n\r\nNavigate to the \"QC\" tab marked \"1\" on the top menu, then click on the \"Departments And Folders\" tab on the sub-menu marked \"2\". The database that will show on the main screen contains the departments records. To access the documents and folders click on the record in question. And to add a new department click on the \"New Category\" button. See image below. \r\n\r\n![DF.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/981/0f6/5f19810f69632694495174.png)\r\n\r\n\r\nStep 2:\r\n\r\nAfter clicking on a record in the database. You will have 2 tabs, one for \"Department Details\" and the other for \"Folders\". These tabs contain attachments/documents.\r\n\r\n![access.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/981/063/5f1981063ec94625847019.png)','<p><strong>Accessing Department details and folders:</strong></p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;QC&quot; tab marked &quot;1&quot; on the top menu, then click on the &quot;Departments And Folders&quot; tab on the sub-menu marked &quot;2&quot;. The database that will show on the main screen contains the departments records. To access the documents and folders click on the record in question. And to add a new department click on the &quot;New Category&quot; button. See image below. </p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/981/0f6/5f19810f69632694495174.png\" alt=\"DF.PNG\" /></p>\n<p>Step 2:</p>\n<p>After clicking on a record in the database. You will have 2 tabs, one for &quot;Department Details&quot; and the other for &quot;Folders&quot;. These tabs contain attachments/documents.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/981/063/5f1981063ec94625847019.png\" alt=\"access.PNG\" /></p>','2020-07-23 22:00:00',1,'2020-07-23 14:33:24','2020-07-23 14:33:24',NULL),(37,25,'Emegency','emegency','','**Emegency Contacts:**\r\n\r\nStep 1:\r\n\r\nNavigate to the \"Operator\" tab marked \"1\" on the top menu, then click on the \"Emegency\" tab on the side-menu marked \"2\". The main screen will display contact details of all management personnel of all departments in the BT-Industrial Group.\r\n\r\n![Emegency.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/985/6e9/5f19856e966e4577854956.png)','<p><strong>Emegency Contacts:</strong></p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;Operator&quot; tab marked &quot;1&quot; on the top menu, then click on the &quot;Emegency&quot; tab on the side-menu marked &quot;2&quot;. The main screen will display contact details of all management personnel of all departments in the BT-Industrial Group.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/985/6e9/5f19856e966e4577854956.png\" alt=\"Emegency.PNG\" /></p>','2020-07-23 23:00:00',1,'2020-07-23 14:50:58','2020-07-23 14:50:58',NULL),(38,25,'Covid 19','covid-19','','**Covid 19 Data:**\r\n\r\nStep 1:\r\n\r\nNavigate to the \"SHEQ\" tab marked \"1\" on the top menu, then click on the \"Covid 19\" tab on the side-menu. Teh database that will appear contains all data and records on Covid 19 on the factory. You can click on a record to access more info about the record rg( screening data, infections recorded etc.). See image below.\r\n\r\n\r\n![Covid.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/98a/75c/5f198a75cb358641261347.png)\r\n\r\nStep 2:\r\n\r\nTo add a new record click on the \"New Covid Screen\" button. On this form you can enter a new record concerning covid 19 data and attachments. When you done filling the form click on the \"Save And Close\" button. See image below.\r\n\r\n\r\n\r\n![new record.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/98c/c23/5f198cc231d1d748053912.png)','<p><strong>Covid 19 Data:</strong></p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;SHEQ&quot; tab marked &quot;1&quot; on the top menu, then click on the &quot;Covid 19&quot; tab on the side-menu. Teh database that will appear contains all data and records on Covid 19 on the factory. You can click on a record to access more info about the record rg( screening data, infections recorded etc.). See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/98a/75c/5f198a75cb358641261347.png\" alt=\"Covid.PNG\" /></p>\n<p>Step 2:</p>\n<p>To add a new record click on the &quot;New Covid Screen&quot; button. On this form you can enter a new record concerning covid 19 data and attachments. When you done filling the form click on the &quot;Save And Close&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/98c/c23/5f198cc231d1d748053912.png\" alt=\"new record.PNG\" /></p>','2020-07-23 23:00:00',1,'2020-07-23 15:14:50','2020-07-23 15:14:50',NULL),(39,25,'Injuries','injuries','','**Accessing injury database:** \r\n\r\nStep 1:\r\n\r\nNavigate to the \"SHEQ\" tab marked \"1\" on the top menu, then click on the \"Injuries\" tab marked \"2\" on the side-menu. The database that appears on the screen contains data on recorded injuries on the site. For more info on injury click on the record in question. You can also add a new injury by clicking on the \"New Injury\" button. See image below.\r\n\r\n\r\n![Injuries.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/995/169/5f19951697a3a095756876.png)\r\n\r\n\r\nStep 2:\r\n\r\nOn this form you can add an new injury record, scale of injury and image. Then you can click on the \"Save And Close\" button. See image below.\r\n\r\n![New Inury.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/997/555/5f19975550484570763844.png)','<p><strong>Accessing injury database:</strong> </p>\n<p>Step 1:</p>\n<p>Navigate to the &quot;SHEQ&quot; tab marked &quot;1&quot; on the top menu, then click on the &quot;Injuries&quot; tab marked &quot;2&quot; on the side-menu. The database that appears on the screen contains data on recorded injuries on the site. For more info on injury click on the record in question. You can also add a new injury by clicking on the &quot;New Injury&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/995/169/5f19951697a3a095756876.png\" alt=\"Injuries.PNG\" /></p>\n<p>Step 2:</p>\n<p>On this form you can add an new injury record, scale of injury and image. Then you can click on the &quot;Save And Close&quot; button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f1/997/555/5f19975550484570763844.png\" alt=\"New Inury.PNG\" /></p>','2020-07-23 23:00:00',1,'2020-07-23 16:00:55','2020-07-23 16:00:55',NULL),(40,25,'Export Button','export-button','','**Export Button**\r\n\r\nThe export button is used to download the database you are currently viewing. This function downloads the database saving it with a \".csv\" extension.\r\n\r\nStep 1:\r\n\r\nAbove the Database table, click on the \"Export\" button. See image below.\r\n\r\n\r\n\r\n![Step 1.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f3/255/d24/5f3255d2465c8626413199.png)\r\n\r\nStep 2:\r\n\r\nOn this page you can click on the check boxes next to the columns names to select which columns should be downloaded with the database. Then click on the \"Export records\" button, see image below.\r\n\r\n![Step 2 .PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f3/255/dbc/5f3255dbcfdc8585557106.png)','<p><strong>Export Button</strong></p>\n<p>The export button is used to download the database you are currently viewing. This function downloads the database saving it with a \".csv\" extension.</p>\n<p>Step 1:</p>\n<p>Above the Database table, click on the \"Export\" button. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f3/255/d24/5f3255d2465c8626413199.png\" alt=\"Step 1.PNG\" /></p>\n<p>Step 2:</p>\n<p>On this page you can click on the check boxes next to the columns names to select which columns should be downloaded with the database. Then click on the \"Export records\" button, see image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f3/255/dbc/5f3255dbcfdc8585557106.png\" alt=\"Step 2 .PNG\" /></p>','2020-08-07 09:44:25',1,'2020-08-11 09:55:54','2020-08-11 10:26:23',NULL),(41,25,'Sorting And Filtering Tables','sorting-and-filtering-tables','','**Filters.**\r\n\r\nIf the table has an extra row on top of the table with a darker shade of gray, this means you have some filtering options you can perform on the table. The options are listed on this row. You might have check boxes or drop boxes to select your desired filter by colunms. See image below.\r\n\r\n\r\n![Filtering.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f3/257/ff9/5f3257ff9df63343674355.png)\r\n\r\nStep:\r\n\r\nClick on the desired filter column, and click by which entity you would like to filter the table by. Then click on the \"Apply\" button to put the filter to effect, and the \"Clear\" button to remove the filter. See image below\r\n\r\n![Filter 2B.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f3/259/d7b/5f3259d7ba2ce526137961.png)\r\n\r\n**Sorting.**\r\n\r\nIf the colunm names on the database have an arrow next to the name, this means you can sort the table by this colunm in ascending or descending order. You click on the colunm repeatedly to alternate between ascending or descending order. You simply click on the colunm name and the table will be sorted with respect to the colunm you click on. See image below.\r\n\r\n![Sorting.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f3/258/053/5f32580532fb4004669630.png)','<p><strong>Filters.</strong></p>\n<p>If the table has an extra row on top of the table with a darker shade of gray, this means you have some filtering options you can perform on the table. The options are listed on this row. You might have check boxes or drop boxes to select your desired filter by colunms. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f3/257/ff9/5f3257ff9df63343674355.png\" alt=\"Filtering.PNG\" /></p>\n<p>Step:</p>\n<p>Click on the desired filter column, and click by which entity you would like to filter the table by. Then click on the \"Apply\" button to put the filter to effect, and the \"Clear\" button to remove the filter. See image below</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f3/259/d7b/5f3259d7ba2ce526137961.png\" alt=\"Filter 2B.PNG\" /></p>\n<p><strong>Sorting.</strong></p>\n<p>If the colunm names on the database have an arrow next to the name, this means you can sort the table by this colunm in ascending or descending order. You click on the colunm repeatedly to alternate between ascending or descending order. You simply click on the colunm name and the table will be sorted with respect to the colunm you click on. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f3/258/053/5f32580532fb4004669630.png\" alt=\"Sorting.PNG\" /></p>','2020-08-04 11:00:52',1,'2020-08-11 10:59:23','2020-08-11 11:00:32',NULL),(42,25,'BT-Account','bt-account','','**BT Account:**\r\n \r\n This BT Account stores all extra pipes/stock which have not been assigned to any Quote or Order. These are available to be assigned to an order. They have a number of pipes and  a value of the pipes under the BT Account. The BT Account can be accessed from the Production tab and Sales tab.\r\n \r\n <p style=\"color:red\"><b>NB: BT Account will be phased out and will no longer be functioning.</b></p>\r\n \r\n\r\n![BT Account.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f4/378/851/5f43788510107639138902.png)','<p><strong>BT Account:</strong></p>\n<p>This BT Account stores all extra pipes/stock which have not been assigned to any Quote or Order. These are available to be assigned to an order. They have a number of pipes and  a value of the pipes under the BT Account. The BT Account can be accessed from the Production tab and Sales tab.</p>\n<p style=\"color:red\"><b>NB: BT Account will be phased out and will no longer be functioning.</b></p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f4/378/851/5f43788510107639138902.png\" alt=\"BT Account.PNG\" /></p>','2020-06-25 01:55:00',1,'2020-08-24 10:23:36','2021-08-30 07:13:13',NULL),(43,25,'Plant Hours','plant-hours','','**Plant Hours:**\r\n\r\nThis \"Plant Hours\" tab keeps track of the Production team\'s workers attendance. It will receive the data from the SHEQ team, which is using \"The Clock-in System\" to keep track of the employees working hours.\r\n\r\nThis tab has both an \"Import\" and \"Export\" function. The \"Plant Hours\" tab can be located as follows. Click on the \"Production\" tab on the top menu. Then click on the \"Plant\" tab marked 1, then \"Plant Hours\" marked 2. See image below.\r\n\r\n\r\n\r\n![Step 1.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f4/37e/29b/5f437e29bd6a6813772908.png)','<p><strong>Plant Hours:</strong></p>\n<p>This &quot;Plant Hours&quot; tab keeps track of the Production team\'s workers attendance. It will receive the data from the SHEQ team, which is using &quot;The Clock-in System&quot; to keep track of the employees working hours.</p>\n<p>This tab has both an &quot;Import&quot; and &quot;Export&quot; function. The &quot;Plant Hours&quot; tab can be located as follows. Click on the &quot;Production&quot; tab on the top menu. Then click on the &quot;Plant&quot; tab marked 1, then &quot;Plant Hours&quot; marked 2. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f4/37e/29b/5f437e29bd6a6813772908.png\" alt=\"Step 1.PNG\" /></p>','2020-08-17 10:49:04',1,'2020-08-24 10:48:40','2020-08-24 10:51:39',NULL),(44,25,'Import And Export','import-and-export','','**Import And Export Function:**\r\n\r\n\r\n\r\n![Import Export.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f4/380/b2a/5f4380b2aaded869882950.png)\r\n\r\nImport Function:\r\nThe import function allows you to upload a .csv file onto the ERP system, but the databases must have marching fields for import to be possible.\r\n\r\nExport Function:\r\nThe export function allows you to download the database from the ERP system and gets saved onto your personal device.','<p><strong>Import And Export Function:</strong></p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f4/380/b2a/5f4380b2aaded869882950.png\" alt=\"Import Export.PNG\" /></p>\n<p>Import Function:\nThe import function allows you to upload a .csv file onto the ERP system, but the databases must have marching fields for import to be possible.</p>\n<p>Export Function:\nThe export function allows you to download the database from the ERP system and gets saved onto your personal device.</p>','2020-08-11 10:52:37',1,'2020-08-24 11:02:38','2020-08-24 11:02:38',NULL),(45,25,'Help Chat Box','help-chat-box','','**Help Chat Box**\r\n\r\nThe \"Help Chat Box\" is an inbound chat forum that allows you to communicate directly to the ERP admin( Mr NS Sithole). Using this forum you can push forward your queries and problems regarding the ERP system to the administrator. This forum also passes  the address/path of your current page as you type to the administrator. This forum is located at the bottom left of the ERP System.\r\n\r\nPlease make sure you enter you requested personal details on your first use. See image below.\r\n\r\n\r\n\r\n![chat log.PNG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f4/391/bb6/5f4391bb612ff941613553.png)','<p><strong>Help Chat Box</strong></p>\n<p>The &quot;Help Chat Box&quot; is an inbound chat forum that allows you to communicate directly to the ERP admin( Mr NS Sithole). Using this forum you can push forward your queries and problems regarding the ERP system to the administrator. This forum also passes  the address/path of your current page as you type to the administrator. This forum is located at the bottom left of the ERP System.</p>\n<p>Please make sure you enter you requested personal details on your first use. See image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5f4/391/bb6/5f4391bb612ff941613553.png\" alt=\"chat log.PNG\" /></p>','2020-08-11 12:11:08',1,'2020-08-24 12:10:44','2020-08-24 12:10:44',NULL),(46,25,'Request Pipe Certificates','request-pipe-certificates','','**Step: 1** - Navigating to the  **Request Pipe Certificates** Tab\r\n\r\nNavigate to the *Sales* tab and \"List\" under \"Quotes\" on the side left menu. In the *New Quote List* page, click on the desired Quote/Record to access more data on the quote.\r\n\r\n![New Quote tab.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a63/967/5faa6396784a9844835106.jpg)\r\n\r\n**Step: 2** - Create Request\r\n\r\nIn the *Edit Quote* page, click on the *Request COC/COA* tab marked *1*, then click on the \"Create Requests\" button marked *2*. See Image below.\r\n\r\n\r\n![Create  Request btn.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a66/45c/5faa6645ce0e9019279011.jpg)\r\n\r\n**Step: 3** - Adding items to the request\r\n\r\nAfter clicking the \"Create Requests\" button, a pop up form will appear. On this form you\'ll have 2 check boxes where you tick on either one or both COC and COA. To add specific pipes of the Quote, click on the \"ADD NEW ITEM\" button. This function gives you access to only the pipes in the \"Quote Items\" for the client. After the creation of the request, click on the \"Create\" button on the bottom right of the form.\r\n\r\nPlease acknowledge that only certificates of produced/completed pipes will be compiled. \r\n\r\n**Important Note**: Only QC can upload the required documents. Leave the upload fields empty.\r\n\r\n![Create pop up.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a68/ffe/5faa68ffead1d234327114.jpg)\r\n\r\n**Final Step** - Send notification to Sales, then **Save** and **Close**.\r\n\r\nAt this stage the record you\'ve created has a \"Send Request\" button. The send request function will send QC a notification of your request. The certificates will be available in the same request entry (database table). After you have done it all, please save and close.\r\n\r\n\r\n![Send- 2 .JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a6f/c4c/5faa6fc4cc480099379461.jpg)','<p><strong>Step: 1</strong> - Navigating to the  <strong>Request Pipe Certificates</strong> Tab</p>\n<p>Navigate to the <em>Sales</em> tab and &quot;List&quot; under &quot;Quotes&quot; on the side left menu. In the <em>New Quote List</em> page, click on the desired Quote/Record to access more data on the quote.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a63/967/5faa6396784a9844835106.jpg\" alt=\"New Quote tab.JPG\" /></p>\n<p><strong>Step: 2</strong> - Create Request</p>\n<p>In the <em>Edit Quote</em> page, click on the <em>Request COC/COA</em> tab marked <em>1</em>, then click on the &quot;Create Requests&quot; button marked <em>2</em>. See Image below.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a66/45c/5faa6645ce0e9019279011.jpg\" alt=\"Create  Request btn.JPG\" /></p>\n<p><strong>Step: 3</strong> - Adding items to the request</p>\n<p>After clicking the &quot;Create Requests&quot; button, a pop up form will appear. On this form you\'ll have 2 check boxes where you tick on either one or both COC and COA. To add specific pipes of the Quote, click on the &quot;ADD NEW ITEM&quot; button. This function gives you access to only the pipes in the &quot;Quote Items&quot; for the client. After the creation of the request, click on the &quot;Create&quot; button on the bottom right of the form.</p>\n<p>Please acknowledge that only certificates of produced/completed pipes will be compiled. </p>\n<p><strong>Important Note</strong>: Only QC can upload the required documents. Leave the upload fields empty.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a68/ffe/5faa68ffead1d234327114.jpg\" alt=\"Create pop up.JPG\" /></p>\n<p><strong>Final Step</strong> - Send notification to Sales, then <strong>Save</strong> and <strong>Close</strong>.</p>\n<p>At this stage the record you\'ve created has a &quot;Send Request&quot; button. The send request function will send QC a notification of your request. The certificates will be available in the same request entry (database table). After you have done it all, please save and close.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a6f/c4c/5faa6fc4cc480099379461.jpg\" alt=\"Send- 2 .JPG\" /></p>','2020-11-10 02:00:00',1,'2020-11-10 12:24:16','2020-11-10 14:02:32',NULL),(47,25,'QC Requested Certificates','qc-requested-certificates','','**Step: 1** - Navigating \r\n\r\nClick on the \"QC\" tab on the top menu, then click on \"Requested Certificates\" under \"Documents\" on the lefthand side menu. The page that is loaded consists of the requested data from Sales. Preloaded there is the COC and COA fields which will state the certificates requested. Click on the record/quote to update or load certificates.\r\n\r\n\r\n![qc certificates.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a78/9c7/5faa789c73f62331196194.jpg)\r\n\r\nStep: 2  - Upload Certificates\r\n\r\nOn this page you\'ll upload the requested files. When the requested files have been uploaded, you can notify the Salesperson by clicking the button \"Notify Sales\". Do not forget to mark that the request has been completed. Please \"Save and Close\" when done.\r\n\r\n![upload.JPG](http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a7a/3b8/5faa7a3b84527073511476.jpg)','<p><strong>Step: 1</strong> - Navigating </p>\n<p>Click on the &quot;QC&quot; tab on the top menu, then click on &quot;Requested Certificates&quot; under &quot;Documents&quot; on the lefthand side menu. The page that is loaded consists of the requested data from Sales. Preloaded there is the COC and COA fields which will state the certificates requested. Click on the record/quote to update or load certificates.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a78/9c7/5faa789c73f62331196194.jpg\" alt=\"qc certificates.JPG\" /></p>\n<p>Step: 2  - Upload Certificates</p>\n<p>On this page you\'ll upload the requested files. When the requested files have been uploaded, you can notify the Salesperson by clicking the button &quot;Notify Sales&quot;. Do not forget to mark that the request has been completed. Please &quot;Save and Close&quot; when done.</p>\n<p><img src=\"http://bailaerp.bt-industrial.co.za/storage/app/uploads/public/5fa/a7a/3b8/5faa7a3b84527073511476.jpg\" alt=\"upload.JPG\" /></p>','2020-11-10 02:00:00',1,'2020-11-10 13:40:55','2020-11-10 14:06:20',NULL),(48,37,'Adding Items to Quote','adding-items-quote','','There are a number of ways to add items to a quote. Before, the most common way to add items to a quote would be the way shown below.\r\n\r\n![ezgif.com-gif-maker (7).gif](https://bailaerp.bt-industrial.co.za/storage/app/uploads/public/600/f97/22d/600f9722d4626547707765.gif)\r\n\r\nThe above image shows the quote being created on the front-end and items have to be added on the same quote after creation, risking duplication.\r\n\r\nAn alternative (and more accurate) way would be to use the backend of the ERP.\r\n\r\nBy going to the **Sales top** tab and **List side** tab, you can go to the **Quote Details** of the quote that you click on. Afterwards, you can create an item on the **Item Wish** tab at the bottom (next to the **Item Wish Catalogue**) \r\n\r\n![ezgif.com-gif-maker (4).gif](https://bailaerp.bt-industrial.co.za/storage/app/uploads/public/600/e93/a68/600e93a68c7a6683361439.gif)\r\n\r\nThis is a better way of implementing changes to the quote without the risk of creating duplicates.\r\n\r\nAll of this is demonstrated by the image below.\r\n\r\n![ezgif.com-gif-maker (6).gif](https://bailaerp.bt-industrial.co.za/storage/app/uploads/public/600/f21/128/600f21128f687440839725.gif)','<p>There are a number of ways to add items to a quote. Before, the most common way to add items to a quote would be the way shown below.</p>\n<p><img src=\"https://bailaerp.bt-industrial.co.za/storage/app/uploads/public/600/f97/22d/600f9722d4626547707765.gif\" alt=\"ezgif.com-gif-maker (7).gif\" /></p>\n<p>The above image shows the quote being created on the front-end and items have to be added on the same quote after creation, risking duplication.</p>\n<p>An alternative (and more accurate) way would be to use the backend of the ERP.</p>\n<p>By going to the <strong>Sales top</strong> tab and <strong>List side</strong> tab, you can go to the <strong>Quote Details</strong> of the quote that you click on. Afterwards, you can create an item on the <strong>Item Wish</strong> tab at the bottom (next to the <strong>Item Wish Catalogue</strong>) </p>\n<p><img src=\"https://bailaerp.bt-industrial.co.za/storage/app/uploads/public/600/e93/a68/600e93a68c7a6683361439.gif\" alt=\"ezgif.com-gif-maker (4).gif\" /></p>\n<p>This is a better way of implementing changes to the quote without the risk of creating duplicates.</p>\n<p>All of this is demonstrated by the image below.</p>\n<p><img src=\"https://bailaerp.bt-industrial.co.za/storage/app/uploads/public/600/f21/128/600f21128f687440839725.gif\" alt=\"ezgif.com-gif-maker (6).gif\" /></p>','2021-01-25 23:40:00',1,'2021-01-25 11:14:46','2021-08-30 10:47:00',NULL),(49,1,'BT ERP Pipe Search v1','bt-erp-pipe-search-v1','Let\'s have a look at how the Pipe Search function operates. Please see video available.','<iframe width=\"100%\" height=\"500px\" src=\"https://www.youtube.com/embed/TGyMAgKwVoQ\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>','<iframe width=\"100%\" height=\"500px\" src=\"https://www.youtube.com/embed/TGyMAgKwVoQ\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>','2022-06-01 07:33:28',1,'2022-06-13 07:33:40','2022-06-14 07:52:43',NULL),(50,1,'BT ERP Sales Quote v1','bt-erp-sales-quote-v1','Here we will be looking at a brief overview of the Quote functions. Please see video available.','<iframe width=\"100%\" height=\"500\" src=\"https://www.youtube.com/embed/QUKN0xIVuxY\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>','<iframe width=\"100%\" height=\"500\" src=\"https://www.youtube.com/embed/QUKN0xIVuxY\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>','2022-06-01 07:22:52',1,'2022-06-14 07:23:06','2022-06-14 07:53:17',NULL);
